const ROOT=resolve(import.meta.dirname,'..');
const envFile=resolve(ROOT,'.env');
try{for(const line of (await readFile(envFile,'utf8')).split(/\r?\n/)){const m=line.match(/^([A-Z_][A-Z_0-9]*)=(.*)$/);if(m&&!process.env[m[1]])process.env[m[1]]=m[2].replace(/^['"]|['"]$/g,'');}}catch{}
