 if(path==='/api/users'&&method==='PATCH'){admin(session);const x=await payload(req);const id=String(x.id||'');const [[existing]]=await pool.execute('SELECT id,username,role,person_id FROM cmms_users WHERE id=? LIMIT 1',[id]);if(!existing)throw Object.assign(Error('Account not found'),{status:404});const username=String(x.username||'').trim();const role=String(x.role||'');const personId=String(x.personId||'');if(!/^[a-z0-9._-]{3,48}$/i.test(username))throw Object.assign(Error('Username must contain 3–48 letters, digits, dots, hyphens or underscores'),{status:400});if(!['admin','technician'].includes(role))throw Object.assign(Error('Invalid role'),{status:400});if(role==='technician'&&!personId)throw Object.assign(Error('Link the technician to an individual People & teams record'),{status:400});if(role==='technician')await ensureUniqueTechnicianPerson(personId,id);if(x.password!==undefined&&x.password!==''&&!validPassword(x.password))throw Object.assign(Error('New password must contain 12–128 characters'),{status:400});if(id===session.userId&&(role!=='admin'||username!==session.username))throw Object.assign(Error('You cannot change your own username or administrator role while signed in'),{status:400});const [[duplicate]]=await pool.execute('SELECT id FROM cmms_users WHERE username=? AND id<>? LIMIT 1',[username,id]);if(duplicate)throw Object.assign(Error('Username already registered'),{status:409});try{if(x.password){await pool.execute('UPDATE cmms_users SET username=?,role=?,person_id=?,password_hash=? WHERE id=?',[username,role,personId,passwordHash(x.password),id]);}else{await pool.execute('UPDATE cmms_users SET username=?,role=?,person_id=? WHERE id=?',[username,role,personId,id]);}}catch(e){if(e.code==='ER_DUP_ENTRY')throw Object.assign(Error('Username already registered'),{status:409});throw e;}for(const [token,activeSession] of sessions)if(activeSession.userId===id) sessions.delete(token);return json(res,200,{ok:true});}
