function apiError(error){if(error.status)return {status:error.status,message:error.message,code:'REQUEST_REJECTED'};if(error.code==='ER_DUP_ENTRY')return {status:409,message:'A record with this unique value already exists. Check usernames or employee identifiers before retrying.',code:error.code};if(error.code==='ER_NO_REFERENCED_ROW_2')return {status:400,message:'A linked record does not exist. Refresh and select an existing employee or asset.',code:error.code};if(error.code==='ER_DATA_TOO_LONG')return {status:400,message:'One or more field values exceed the database length limit. Shorten the value and retry.',code:error.code};if(error.code==='ER_BAD_NULL_ERROR')return {status:400,message:'A required value is missing. Review all mandatory fields.',code:error.code};if(['ECONNREFUSED','PROTOCOL_CONNECTION_LOST','ETIMEDOUT'].includes(error.code))return {status:503,message:'MariaDB is unavailable. Check that the database service is running and configured correctly.',code:error.code};return {status:500,message:'The operation failed unexpectedly. Contact the CMMS administrator with the reference shown.',code:'INTERNAL_ERROR'};}
createServer((req,res)=>{route(req,res).catch(error=>{const requestId=randomUUID().slice(0,8);const detail=apiError(error);console.error('[CMMS API]',requestId,req.method,req.url,detail.code,error.message);if(!res.headersSent)json(res,detail.status,{error:detail.message,code:detail.code,requestId});else res.destroy();});}).listen(PORT,process.env.CMMS_BIND||'127.0.0.1',()=>console.log(`CMMS MariaDB server: http://${process.env.CMMS_BIND||'127.0.0.1'}:${PORT} (${dbStatus})`));